<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\SiteSetting;use Illuminate\Http\Request;
class SettingsController extends Controller{public function edit(){return view('admin.settings.index',['settings'=>SiteSetting::pluck('value','key')]);}public function update(Request $r){$d=$r->validate(['college_name'=>'nullable|max:255','college_short_name'=>'nullable|max:255','college_site'=>'nullable|max:2048','contact_phone'=>'nullable|max:100','contact_email'=>'nullable|email|max:255','address'=>'nullable|max:500','home_badge'=>'nullable|max:255','home_title'=>'nullable|max:500','home_subtitle'=>'nullable|max:1500','home_about_title'=>'nullable|max:255','home_about_text'=>'nullable|max:5000','footer_text'=>'nullable|max:1000','analytics_code'=>'nullable|max:10000','maintenance_notice'=>'nullable|max:2000']);foreach($d as $k=>$v)SiteSetting::put($k,$v,in_array($k,['home_badge','home_title','home_subtitle','home_about_title','home_about_text'])?'home':'site');return back()->with('success','Настройки сохранены');}}
